1	/* ============================ Đi dạo: vùng đi được và kết cấu trên mặt cầu ============================
2	   Dựng dữ liệu tĩnh cho lõi va chạm (map.ts) từ CONFIG và biên dạng hai cầu. Thuần: chỉ import CONFIG, deckY, shRoadY / SH; không dựng cảnh, không đụng DOM.
3	   Nhà ven sông và chân đế địa danh thêm lúc chạy (Task 6, stAddSolids), không ở đây.
4	   Luật (spec §4, plan "Bậc thấp trên mặt cầu"):
5	   - Mép vùng là nơi TÂM nhân vật tới được: lan can / mép kè lùi vào radius.
6	   - Bậc ≤ stepMax (lề, dải phân cách, mặt đường) cộng sẵn vào y(x, z) của vùng: nhân vật tự bước lên.
7	   - Gờ cao hơn stepMax, thấp hơn lowMax là tường thấp (top = chiều cao thật). Lan can, thân rồng, tháp, tượng: cao vô hạn.
8	   - Không đi dưới gầm cầu: vùng bờ cắt quanh phần cầu cao hơn mặt đất, nối với cầu ở đầu cầu nơi mặt cầu hạ về mặt đường.
9	
10	   Bảng nguồn số (file : dòng của hình học đã đọc; (ước lượng) = số chọn ở đây, không có trong hình học):
11	   | Số | Giá trị | Nguồn |
12	   | Mép kè hai bờ | |x| = 262 | config.ts:22 (bankX) |
13	   | Lan can kè ven sông | cột 0,28 m tại |x| = 263 → mặt trong (phía bờ) 263,14; bỏ ở chân cầu và trước Cầu Tình Yêu | promenade.ts:56-60 |
14	   | Mặt đất / mặt đường bờ | 2,5 / 2,6 m | config.ts:20-21 (landY, roadY) |
15	   | Cầu Rồng: mặt cầu dài | |x| ≤ 333 | config.ts:14 (length), deck.ts:17; deckY(±333) = roadY (profile.ts:7) |
16	   | Cầu Rồng: lan can | tim |z| = 18,65, dày 0,14 → mặt trong 18,58 | deck.ts:23 (hw − 0,1) |
17	   | Cầu Rồng: gờ mép ngoài | tới |z| = 19,0 | deck.ts:26 (hw + 0,1, rộng 0,3) |
18	   | Cầu Rồng: gờ chắn xe | |z| 15,9–16,25, cao 0,9 | deck.ts:14-15,22 (sideIn = 3 + 13,25) |
19	   | Cầu Rồng: lề / dải phân cách / mặt đường | +0,25 / +0,3 (|z| ≤ 3) / +0,02 | deck.ts:21 / 19 / 35 |
20	   | Thân rồng: điểm điều khiển, bán kính | (x, deckY + yr) | body.ts:15-20,27-39; config.ts:15-17,23 |
21	   | Thân rồng: bề ngang | 1,03 r + 0,085 (đai sườn) | body.ts:49,57 |
22	   | Đường nối dài Cầu Rồng trên bờ | đường +0,03 |z| 3–16,25, dải giữa +0,3, vỉa hè +0,2 ở |z| 16,7–19,7, |x| ≥ 333 | streets.ts:15-22 |
23	   | Đường ven sông | tim |x| = 299, mặt đường +0,02 ở 1,5 < |x − 299| ≤ 10,5, dải giữa 3 m +0,3 | streets.ts:25-29 |
24	   | Cầu sông Hàn: tâm | z = −1080, x cục bộ = x thế giới | config.ts:152; SongHanBridge.ts:42 |
25	   | Cầu sông Hàn: mặt cầu + lan can | |x| ≤ 290, cao độ shRoadY | fixedSpans.ts:58; swingSpan.ts:38; profile.ts:10 |
26	   | Cầu sông Hàn: lan can | tim |dz| = 6,3, dày 0,12 → mặt trong 6,24 | common/deck.ts:16 (hw − 0,15) |
27	   | Cầu sông Hàn: gờ chắn bánh | |dz| 4,445–4,695, cao 0,545 | common/deck.ts:14 |
28	   | Cầu sông Hàn: lề / dải giữa / mặt đường | +0,25 / +0,3 (|dz| ≤ 1,1) / +0,03 | common/deck.ts:13; fixedSpans.ts:52, swingSpan.ts:24; fixedSpans.ts:48 |
29	   | Cầu sông Hàn: mố | rộng deckWidth + 1 → |dz| ≤ 6,95 | fixedSpans.ts:18 |
30	   | Cầu sông Hàn: đường nối trên bờ | đường +0,03 ở |dz| 1,1–4,45, dải giữa +0,3, |x| ≥ 290 | fixedSpans.ts:48-55 |
31	   | Nhịp quay | |x| ≤ fixedStart 62,35 | config.ts:193-194 |
32	   | Cột đôi ở tim tháp | x ±0,4, |dz| ≤ 1,0 | swingSpan.ts:45 (z ±0,55, tiết diện 0,9 × 0,8) |
33	   | Chân chữ A | từ (±15, +0,2) tới (0, +19), tiết diện 1,0 × 1,4 | swingSpan.ts:46; config.ts:176-177 |
34	   | Neo dây văng | x 20–59,2, đỉnh 25–36,5 trên cột | swingSpan.ts:58-62; config.ts:179-180 |
35	   | Hộp barie | (±68,35, ±4,6), 0,45 × 1,0 | signals.ts:10-17; config.ts:187 |
36	   | Cầu Tình Yêu | x 224–262, z −78, rộng 6, mặt 3,0 m; lan can kè bỏ ở |z + 78| < 3 + railGap | landmarks.ts:61-62; promenade.ts:55,60 |
37	   | Cầu Tình Yêu: lan can / khóa tình yêu | tim ±2,9, dày 0,12 / ±2,8 dày 0,06 → mặt trong 2,77 | landmarks.ts:64-65 |
38	   | Bệ tượng cá chép | 3,4 × 3,4 tại x 225,8, cao 1,2 | landmarks.ts:66-71 |
39	   | Bến du thuyền bờ Tây | x −254 ± …, z 104, trong lòng sông | promenade.ts:70-76 (không có vùng nào ở |x| < 262 ngoài cầu) |
40	   ============================================================================================================ */
41	import { CONFIG } from '../../config';
42	import { deckY } from '../../bridges/dragon/profile';
43	import { SH, shRoadY } from '../../bridges/song-han/profile';
44	import { stMakeMap, stNearestValid, type StZone, type StSolid, type StMap } from './map';
45	
46	export const ST_GATE_SWING = 'shSwing';
47	
48	const R = CONFIG.stroll.radius, BK = CONFIG.bankX, LAND = CONFIG.landY, ROAD = CONFIG.roadY;
49	const BX = CONFIG.stroll.bounds;
50	const REACH = CONFIG.stroll.reach;
51	const RF_RAIL = BK + 1 + 0.28 / 2;                                  // 263,14 — mặt phía bờ của cột lan can kè (promenade.ts:58-59, x = bankX + 1, cột 0,28 m)
52	const BANK_IN = RF_RAIL + R;                                        // 263,49 — mép vùng bờ: tâm nhân vật không lấn qua lan can kè
53	
54	/* ----- Cầu Rồng (deck.ts) ----- */
55	const DR_X = CONFIG.length / 2;                                     // 333 — hai đầu mặt cầu
56	const DR_HW = CONFIG.width / 2;                                     // 18,75
57	const DR_RAIL_IN = DR_HW - 0.1 - 0.07;                              // 18,58 — mặt trong tay vịn
58	const DR_EDGE = DR_HW + 0.25;                                       // 19,0 — mép ngoài gờ mép
59	const DR_MED = CONFIG.median / 2;                                   // 3
60	const DR_SIDE_IN = DR_MED + CONFIG.lanesPerDir * CONFIG.laneWidth + CONFIG.shoulder;   // 16,25 — mép trong lề
61	const DR_CURB = { z0: DR_SIDE_IN - 0.35, z1: DR_SIDE_IN, top: 0.9 };   // gờ chắn xe
62	const DR_SIDEWALK = 0.25, DR_MEDIAN = 0.3, DR_ROAD = 0.02;          // m trên deckY
63	const DR_ARCH_GAP = 8;                                              // m — gộp hai đoạn thân rồng cách nhau không quá số này: chân vòm là cả đoạn thân cắm xuống rồi trồi lên khỏi mặt cầu (đoạn thân nằm hẳn dưới mặt cầu dài nhất 6,75 m ở x = ±255; giữa hai chân vòm cách ≥ 40 m) (ước lượng)
64	
65	/* ----- Đường trên bờ (streets.ts) ----- */
66	const AX_SIDE = { z0: 16.7, z1: 19.7 };                             // vỉa hè đường nối dài Cầu Rồng, cao +0,2
67	const RV_X = 299, RV_MED = 1.5, RV_HALF = 10.5;                     // đường ven sông Bạch Đằng / Trần Hưng Đạo
68	
69	/* ----- Cầu sông Hàn (fixedSpans.ts, swingSpan.ts, common/deck.ts) ----- */
70	const SHZ = SH.z;
71	const SH_X = 290;                                                   // lan can / lề phần cố định tới |x| = 290 (fixedSpans.ts:58)
72	const SH_RAIL_IN = SH.hw - 0.15 - 0.06;                             // 6,24
73	const SH_EDGE = SH.hw;                                              // 6,45 — mép ngoài gờ mép
74	const SH_ABUT = SH.hw + 0.5;                                        // 6,95 — nửa bề rộng mố
75	const SH_CURB_C = SH.hw - SH.sidewalk + 0.12;                       // 4,57 — tim gờ chắn bánh
76	const SH_CURB = { z0: SH_CURB_C - 0.125, z1: SH_CURB_C + 0.125, top: 0.545 };
77	const SH_MED = SH.median / 2;                                       // 1,1
78	const SH_LANE_OUT = SH.lane + SH.laneWidth / 2;                     // 4,45 — mép ngoài làn xe
79	const SH_SIDEWALK = 0.25, SH_MEDIAN = 0.3, SH_ROAD = 0.03;
80	const SH_LAND_HALF = 7.5;                                           // m — nửa bề rộng vùng đầu cầu trên bờ, chồng 0,2 m lên vùng bờ (ước lượng)
81	
82	/* ----- Cầu Tình Yêu (landmarks.ts) ----- */
83	const LV = CONFIG.riverfront.love, LV_X0 = BK - LV.length;          // 224
84	const LV_IN = LV.width / 2 - 0.2 - 0.03;                            // 2,77 — mặt trong hàng khóa tình yêu
85	const LV_RAIL = LV.width / 2 - 0.1 + 0.06;                          // 2,96 — mặt ngoài tay vịn
86	const LV_DECK = 2.55 + 0.45;                                        // 3,0 — mặt cầu tàu
87	const LV_END = 2.8;                                                 // m — cao độ đứng ở chỗ nối kè: dốc 0,2 m trong 2 m cuối để bậc xuống mặt kè 2,5 ≤ stepMax (ước lượng)
88	const LV_RAMP = 2;                                                  // m — chiều dài đoạn dốc đó (ước lượng)
89	
90	/* ===== Cao độ đứng ===== */
91	function stDragonY(x: number, z: number): number {
92	  const az = Math.abs(z), base = deckY(x);
93	  if (az <= DR_MED) return base + DR_MEDIAN;
94	  if (az < (DR_CURB.z0 + DR_CURB.z1) / 2) return base + DR_ROAD;
95	  return base + DR_SIDEWALK;
96	}
97	function stSongHanY(x: number, z: number): number {
98	  const adz = Math.abs(z - SHZ), base = shRoadY(x);
99	  if (adz <= SH_MED) return base + SH_MEDIAN;
100	  if (adz < SH_CURB_C) return base + SH_ROAD;
101	  return base + SH_SIDEWALK;
102	}
103	/* Mặt bờ: mặt đất, cộng mặt đường / dải phân cách / vỉa hè nơi có (lấy mặt cao nhất, như khối nào nằm trên cùng) */
104	function stBankY(x: number, z: number): number {
105	  const ax = Math.abs(x), az = Math.abs(z), adz = Math.abs(z - SHZ), ar = Math.abs(ax - RV_X);
106	  let y = LAND;
107	  if (ax >= DR_X) {                                                 // Nguyễn Văn Linh / Võ Văn Kiệt
108	    if (az <= DR_MED) y = Math.max(y, ROAD + 0.3);
109	    else if (az <= DR_SIDE_IN) y = Math.max(y, ROAD + 0.03);
110	    else if (az >= AX_SIDE.z0 && az <= AX_SIDE.z1) y = Math.max(y, ROAD + 0.2);
111	  }
112	  if (ax >= SH_X) {                                                 // Lê Duẩn / Phạm Văn Đồng
113	    if (adz <= SH_MED) y = Math.max(y, ROAD + 0.3);
114	    else if (adz <= SH_LANE_OUT) y = Math.max(y, ROAD + 0.03);
115	  }
116	  if (ar <= RV_MED) y = Math.max(y, ROAD + 0.3);                    // Bạch Đằng / Trần Hưng Đạo
117	  else if (ar <= RV_HALF) y = Math.max(y, ROAD + 0.02);
118	  return y;
119	}
120	function stLoveY(x: number): number {
121	  const xr = BANK_IN - LV_RAMP;
122	  return x <= xr ? LV_DECK : LV_DECK + (LV_END - LV_DECK) * (x - xr) / LV_RAMP;
123	}
124	
125	/* ===== Vùng đi được (thứ tự = ưu tiên khi chồng nhau) ===== */
126	export function stBuildZones(): StZone[] {
127	  const zs: StZone[] = [];
128	  const add = (id: string, x0: number, x1: number, z0: number, z1: number, y: StZone['y'], gate?: string) => {
129	    const zn: StZone = { id, x0, x1, z0, z1, y }; if (gate) zn.gate = gate; zs.push(zn);
130	  };
131	  const shH = SH_RAIL_IN - R;                                       // 5,89
132	  /* Cầu sông Hàn: nhịp quay có cổng, hai phần cố định tới |x| = 290 nơi mặt cầu về 2,6 m */
133	  add('shSwing', -SH.fixedStart, SH.fixedStart, SHZ - shH, SHZ + shH, stSongHanY, ST_GATE_SWING);
134	  add('songHanW', -SH_X, -SH.fixedStart, SHZ - shH, SHZ + shH, stSongHanY);
135	  add('songHanE', SH.fixedStart, SH_X, SHZ - shH, SHZ + shH, stSongHanY);
136	  /* Cầu Rồng: cả bề rộng giữa hai lan can */
137	  const drH = DR_RAIL_IN - R;                                       // 18,23
138	  add('dragon', -DR_X, DR_X, -drH, drH, stDragonY);
139	  /* Cầu Tình Yêu: kéo vào bờ qua khe lan can kè (promenade.ts bỏ lan can ở |z − love.z| < width/2 + railGap); lối vào duy nhất là cạnh x = BANK_IN chung với vùng bờ Đông */
140	  add('love', LV_X0 + R, BANK_IN, LV.z - (LV_IN - R), LV.z + (LV_IN - R), stLoveY);
141	  /* đầu cầu trên bờ: đường nối dài, cùng cao độ với vùng bờ */
142	  for (const [id, s] of [['dragonW', -1], ['dragonE', 1]] as [string, number][]) {
143	    add(id, s < 0 ? BX.x0 : DR_X, s < 0 ? -DR_X : BX.x1, -AX_SIDE.z1, AX_SIDE.z1, stBankY);
144	  }
145	  for (const [id, s] of [['shLandW', -1], ['shLandE', 1]] as [string, number][]) {
146	    add(id, s < 0 ? BX.x0 : SH_X, s < 0 ? -SH_X : BX.x1, SHZ - SH_LAND_HALF, SHZ + SH_LAND_HALF, stBankY);
147	  }
148	  /* hai bờ: từ lan can kè lùi radius (cả chỗ không có lan can ở chân cầu: vùng bờ đã cắt quanh cầu) ra tới hết khung; cắt quanh thân Cầu Rồng (|z| < 19,35) và thân Cầu sông Hàn (|dz| < 7,3) */
149	  const drCut = DR_EDGE + R, shCut = SH_ABUT + R;
150	  for (const [id, s] of [['bankW', -1], ['bankE', 1]] as [string, number][]) {
151	    const x0 = s < 0 ? BX.x0 : BANK_IN, x1 = s < 0 ? -BANK_IN : BX.x1;
152	    add(id, x0, x1, BX.z0, SHZ - shCut, stBankY);
153	    add(id, x0, x1, SHZ + shCut, -drCut, stBankY);
154	    add(id, x0, x1, drCut, BX.z1, stBankY);
155	  }
156	  return zs;
157	}
158	
159	/* ===== Đường tim thân rồng: chép điểm điều khiển body.ts:27-38 và CatmullRomCurve3 centripetal của three (không import three) ===== */
160	export function stSpinePoints(): [number, number][] {
161	  const pts: [number, number][] = [];
162	  const add = (x: number, yr: number) => pts.push([x, deckY(x) + yr]);
163	  add(-366, 11); add(-361, 16); add(-354, 17.5); add(-347, 14); add(-340, 8.5); add(-331, 4.5); add(-316, 3.0); add(-298, 3.4); add(-276, 2.4);
164	  let x0 = -CONFIG.mainTotal / 2; add(x0, -3);
165	  for (const s of CONFIG.mainSpans) {
166	    const rise = CONFIG.spanRise[s];
167	    for (const t of [0.12, 0.28, 0.5, 0.72, 0.88]) add(x0 + s * t, -3 + (rise + 3) * Math.sin(Math.PI * t));
168	    x0 += s; add(x0, -3);
169	  }
170	  add(272, 2.4); add(289, 3.0); add(303, 4.6); add(314, 7.4); add(323, 10.4); add(330, 13);
171	  return pts;
172	}
173	/* Một trục của đa thức Catmull-Rom không đều (giống CubicPoly.initNonuniformCatmullRom của three) */
174	function stCr(a: number, b: number, c: number, d: number, dt0: number, dt1: number, dt2: number, t: number): number {
175	  const t1 = ((b - a) / dt0 - (c - a) / (dt0 + dt1) + (c - b) / dt1) * dt1;
176	  const t2 = ((c - b) / dt1 - (d - b) / (dt1 + dt2) + (d - c) / dt2) * dt1;
177	  const c2 = -3 * b + 3 * c - 2 * t1 - t2, c3 = 2 * b - 2 * c + t1 + t2;
178	  return b + t1 * t + c2 * t * t + c3 * t * t * t;
179	}
180	export function stSpinePoint(pts: [number, number][], t: number, out: { x: number; y: number }): void {
181	  const l = pts.length, p = (l - 1) * t;
182	  let i = Math.floor(p), w = p - i;
183	  if (w === 0 && i === l - 1) { i = l - 2; w = 1; }
184	  const p1 = pts[i], p2 = pts[i + 1];
185	  const p0: [number, number] = i > 0 ? pts[i - 1] : [2 * pts[0][0] - pts[1][0], 2 * pts[0][1] - pts[1][1]];
186	  const p3: [number, number] = i + 2 < l ? pts[i + 2] : [2 * pts[l - 1][0] - pts[l - 2][0], 2 * pts[l - 1][1] - pts[l - 2][1]];
187	  const d = (a: [number, number], b: [number, number]) => Math.pow((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2, 0.25);
188	  let dt0 = d(p0, p1), dt1 = d(p1, p2), dt2 = d(p2, p3);
189	  if (dt1 < 1e-4) dt1 = 1;
190	  if (dt0 < 1e-4) dt0 = dt1;
191	  if (dt2 < 1e-4) dt2 = dt1;
192	  out.x = stCr(p0[0], p1[0], p2[0], p3[0], dt0, dt1, dt2, w);
193	  out.y = stCr(p0[1], p1[1], p2[1], p3[1], dt0, dt1, dt2, w);
194	}
195	
196	/* Bán kính thân theo phần độ dài cung u (body.ts:15-20) */
197	function stSpineRadius(u: number): number {
198	  const Rb = CONFIG.bodyRadius, sm = (t: number) => t * t * (3 - 2 * t);
199	  if (u < 0.06) return 0.25 + (Rb - 0.25) * sm(u / 0.06);
200	  if (u > 0.95) return Rb + (CONFIG.headRadius - Rb) * sm((u - 0.95) / 0.05);
201	  return Rb;
202	}
203	
204	/* Thân / chân vòm / đầu / đuôi rồng trong tầm người: lấy mẫu đường tim, đánh dấu ô x (0,25 m) nơi ống thân (mặt cắt dọc z = 0)
205	   chạm dải [mặt cầu, mặt cầu + dải phân cách + REACH]; gộp ô liền nhau thành hình chữ nhật trên dải phân cách. */
206	function stDragonSolids(): StSolid[] {
207	  const pts = stSpinePoints(), N = 8000, p = { x: 0, y: 0 };
208	  const xs = new Float64Array(N + 1), ys = new Float64Array(N + 1), len = new Float64Array(N + 1);
209	  for (let i = 0; i <= N; i++) {
210	    stSpinePoint(pts, i / N, p); xs[i] = p.x; ys[i] = p.y;
211	    if (i > 0) len[i] = len[i - 1] + Math.hypot(xs[i] - xs[i - 1], ys[i] - ys[i - 1]);
212	  }
213	  const X0 = -400, STEP = 0.25, M = Math.round(800 / STEP) + 1;
214	  const half = new Float64Array(M);                                 // 0 = ô trống, > 0 = nửa bề ngang thân tại ô
215	  for (let i = 0; i <= N; i++) {
216	    const r = stSpineRadius(len[i] / len[N]), rr = 1.03 * r + 0.085;
217	    const g0 = Math.max(0, Math.ceil((xs[i] - rr - X0) / STEP)), g1 = Math.min(M - 1, Math.floor((xs[i] + rr - X0) / STEP));
218	    for (let g = g0; g <= g1; g++) {
219	      const x = X0 + g * STEP, lo = deckY(x), hi = lo + DR_MEDIAN + REACH;
220	      const yb = ys[i] < lo ? lo : ys[i] > hi ? hi : ys[i];
221	      const dx = xs[i] - x, dy = ys[i] - yb;
222	      if (dx * dx + dy * dy < rr * rr && rr > half[g]) half[g] = rr;
223	    }
224	  }
225	  const out: StSolid[] = [];
226	  let cur: StSolid = null, last = -Infinity;
227	  for (let g = 0; g < M; g++) {
228	    if (half[g] === 0) continue;
229	    const x = X0 + g * STEP;
230	    if (cur && x - last <= DR_ARCH_GAP) { cur.x1 = x + STEP; cur.z1 = Math.max(cur.z1, half[g]); cur.z0 = -cur.z1; }
231	    else { cur = { kind: 'rect', x0: x - STEP, x1: x + STEP, z0: -half[g], z1: half[g] }; out.push(cur); }
232	    last = x;
233	  }
234	  return out;
235	}
236	
237	/* Tháp chữ A, cột đôi, neo dây văng, hộp barie Cầu sông Hàn (tọa độ cục bộ + z cầu) */
238	function stSongHanSolids(): StSolid[] {
239	  const out: StSolid[] = [];
240	  const rect = (x0: number, x1: number, dz0: number, dz1: number, top?: number) => {
241	    const s: StSolid = { kind: 'rect', x0, x1, z0: SHZ + dz0, z1: SHZ + dz1 }; if (top !== undefined) s.top = top; out.push(s);
242	  };
243	  const H = SH_MEDIAN + REACH;                                      // tầm chặn tính từ mặt cầu, m
244	  rect(-0.4, 0.4, -1.0, 1.0);                                       // cột đôi ở tim (swingSpan.ts:45)
245	  const legIn = SH.aFoot - SH.aFoot * (H - 0.2) / (SH.aApex - 0.2); // ≈ 12,9 m — chân chữ A lên tới tầm H
246	  for (const s of [-1, 1]) {
247	    const a = legIn - 0.9, b = SH.aFoot + 0.9;                      // + nửa tiết diện 1,4 m chiếu ngang, làm tròn lên 0,9 (ước lượng)
248	    rect(s < 0 ? -b : a, s < 0 ? -a : b, -0.5, 0.5);                // chân chữ A, rộng 1,0 theo z
249	    for (let i = 0; i < SH.stays; i++) {                            // neo dây văng: dây thấp hơn tầm H trong đoạn gần neo
250	      const k = i / (SH.stays - 1), xd = SH.stayDeck[1] + (SH.stayDeck[0] - SH.stayDeck[1]) * k, top = SH.stayTop[1] + (SH.stayTop[0] - SH.stayTop[1]) * k;
251	      const xin = xd - (H - 0.35) * (xd - 0.5) / (top - 0.35);
252	      const a2 = xin - 0.1, b2 = xd + 0.3;                          // + bán kính dây, đầu neo (ước lượng)
253	      rect(s < 0 ? -b2 : a2, s < 0 ? -a2 : b2, -0.15, 0.15);        // dây 0,07 m + neo (ước lượng)
254	    }
255	    for (const sz of [-1, 1]) {                                     // hộp barie 0,45 × 1,0 trên gờ chắn bánh
256	      const bz = sz * (SH.hw - SH.sidewalk + 0.15);
257	      rect(s * SH.barrierX - 0.225, s * SH.barrierX + 0.225, bz - 0.225, bz + 0.225);
258	    }
259	    rect(-SH_X, SH_X, s < 0 ? -SH_CURB.z1 : SH_CURB.z0, s < 0 ? -SH_CURB.z0 : SH_CURB.z1, SH_CURB.top);   // gờ chắn bánh, liền qua khe nhịp quay
260	    for (const [x0, x1] of [[-SH_X, -SH.fixedStart], [SH.fixedStart, SH_X]]) {
261	      rect(x0, x1, s < 0 ? -SH_EDGE : SH_RAIL_IN, s < 0 ? -SH_RAIL_IN : SH_EDGE);   // lan can phần cố định (chặn hai đầu ở |x| = 290)
262	    }
263	  }
264	  return out;
265	}
266	
267	export function stBuildStructures(): StSolid[] {
268	  const out: StSolid[] = stDragonSolids();
269	  for (const s of [-1, 1]) {
270	    out.push({ kind: 'rect', x0: -DR_X, x1: DR_X, z0: s < 0 ? -DR_EDGE : DR_RAIL_IN, z1: s < 0 ? -DR_RAIL_IN : DR_EDGE });                 // lan can Cầu Rồng
271	    out.push({ kind: 'rect', x0: -DR_X, x1: DR_X, z0: s < 0 ? -DR_CURB.z1 : DR_CURB.z0, z1: s < 0 ? -DR_CURB.z0 : DR_CURB.z1, top: DR_CURB.top });   // gờ chắn xe
272	    out.push({ kind: 'rect', x0: LV_X0, x1: BK, z0: s < 0 ? LV.z - LV_RAIL : LV.z + LV_IN, z1: s < 0 ? LV.z - LV_IN : LV.z + LV_RAIL });      // lan can + khóa Cầu Tình Yêu
273	  }
274	  out.push(...stSongHanSolids());
275	  out.push({ kind: 'rect', x0: LV_X0 + 1.8 - 1.7, x1: LV_X0 + 1.8 + 1.7, z0: LV.z - 1.7, z1: LV.z + 1.7 });   // bệ + tượng cá chép hóa rồng (bệ cao 1,2 > lowMax)
276	  return out;
277	}
278	
279	export function stBuildStaticMap(): StMap {
280	  return stMakeMap(stBuildZones(), stBuildStructures(), CONFIG.stroll.radius);
281	}
282	
283	/* Điểm xuất phát slot: lệch theo x quanh spawn; slot < 0 (đi một mình) dùng giữa. Gọi một lần lúc vào chế độ, không mỗi khung */
284	export function stSpawn(map: StMap, slot: number, out: { x: number; z: number }): void {
285	  const S = CONFIG.stroll.spawn, k = slot < 0 ? 2 : slot;
286	  const x = S.x + S.spread * (k - 2), z = S.z;
287	  if (!stNearestValid(map, x, z, out)) { out.x = x; out.z = z; }
288	}
289

