10	/* [deck] dầm hộp 34,5 m, 6 làn, dải phân cách 5,5 m, lề, lan can, đèn, dải LED */
11	export function ttlBuildDeck(bridge: TranThiLyBridge) {
12	  const M = bridge.mats, hw = TTL.hw, W = TTL.westEnd, E = TTL.eastEnd, xr0 = -470, xr1 = 450;
13	  // Dầm hộp BTCT: bản mặt rộng 34,5 m, cánh hẫng mỏng dần hai bên, hộp giữa sườn vát (tiết diện ước lượng)
14	  const sec = [[-hw, 0], [hw, 0], [hw, -0.35], [11, -0.75], [9, -TTL.girderDepth], [-9, -TTL.girderDepth], [-11, -0.75], [-hw, -0.35]];
