const boats: RiverBoat[] = [];
let fleet: BoatFleet;
export const RIVER_CROWD_FIRST = 7;   // instance 7.. dành cho tàu tụ tập
export function buildBoats() {
  const lanesX = [-48, -22, 22, 48];
