    // giữ đúng 2 lời gọi rand() mỗi tàu, đúng thứ tự (speed rồi len) — bất biến chuỗi seed; r đổi sang khoảng dài của kiểu
    const speed = 3 + rand() * 2, r = rand(), type: BoatTypeId = i % 2 ? 'B' : 'A', [lo, hi] = CONFIG.boats.types[type].len;

